def find_golomb_ruler(n_marks, max_length=100):
    """Find a Golomb ruler with n_marks using backtracking."""
    marks = [0]

    def backtrack(current_marks):
        if len(current_marks) == n_marks:
            return current_marks[:]

        # Try adding next mark
        start = current_marks[-1] + 1
        for next_mark in range(start, max_length + 1):
            # Check if adding this mark creates any duplicate differences
            valid = True
            for m in current_marks:
                diff = next_mark - m
                # Check if this difference already exists
                for i in range(len(current_marks)):
                    for j in range(i+1, len(current_marks)):
                        if current_marks[j] - current_marks[i] == diff:
                            valid = False
                            break
                    if not valid:
                        break
                if not valid:
                    break

            if valid:
                current_marks.append(next_mark)
                result = backtrack(current_marks)
                if result:
                    return result
                current_marks.pop()

        return None

    return backtrack(marks)

# Try to find one
result = find_golomb_ruler(10, max_length=80)
if result:
    print(f"\nFound ruler: {result}")
    valid, msg = verify_golomb_ruler(result)
    print(f"Valid: {valid}, {msg}")
else:
    print("\nNo ruler found with max_length=80")
